from flask import Flask, request, jsonify
from twilio.twiml.voice_response import VoiceResponse
import requests

app = Flask(__name__)

@app.route("/voice", methods=['POST'])
def voice():
    response = VoiceResponse()
    response.say("Welcome to Skyscraper HQ. Please choose an option.")
    response.gather(input='speech', action='/gather', method='POST')
    return str(response)

@app.route("/gather", methods=['POST'])
def gather():
    speech_result = request.form.get('SpeechResult')
    # POST to local API
    api_response = requests.post("http://localhost/api/f0/converse", json={"input": speech_result})
    reply = api_response.json().get('reply', "Sorry, I didn't understand that.")
    response = VoiceResponse()
    response.say(reply)
    return str(response)

if __name__ == "__main__":
    app.run(debug=True)

